import React, { useCallback, useEffect, useState } from "react";
import Popup from "./Popup";
import { useNavigate, useParams } from "react-router";
import { Member } from "../Model/Member.model";
import axios from "axios";
import GroupNavBar from "./GroupNavBar";
import { Container, Flex, Paper, Button, ButtonGroup } from "@mantine/core";
import { IconUser } from "@tabler/icons-react";

function Group() {
  const [showPopup, setShowPopup] = useState<boolean>(false);
  const [members, setMembers] = useState<Member[]>([]);
  const { groupId } = useParams<{ groupId: string }>();
  const navigate = useNavigate();

  const openTransaction = () => {
    navigate("transaction");
  };
  const openTransactions = () => {
    navigate("transactions");
  };

  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const onSettle = (id: string) => {
    axios
      .put<Member>(`http://localhost:5257/api/Member/${id}`)
      .then((response) => {
        fetchMembers();
        alert("Settled");
      })
      .catch(() => {});
  };

  const onDelete = (id: string) => {
    axios
      .delete(`http://localhost:5257/api/Member/${id}`)
      .then(() => {
        setMembers((old) => old.filter((i) => i.id !== id));
        alert("Member deleted");
      })
      .catch(() => {
        alert("Member not settled");
      });
  };

  const fetchMembers = useCallback(() => {
    axios
      .get<Member[]>(`http://localhost:5257/Group/${groupId}/Member`)
      .then((response) => {
        setMembers(response.data);
        console.log(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, [groupId]);

  useEffect(() => {
    fetchMembers();
  }, [fetchMembers]);

  const onCreateMember = (value: string) => {
    axios
      .post<Member>(`http://localhost:5257/Group/${groupId}`, { name: value })
      .then((response) => {
        setMembers((old) => [...old, response.data]);
      })
      .catch((error) => {
        alert("Name cannot be empty");
      });
  };
  return (
    <>
      <Paper>
        <GroupNavBar handlePopup={handleOpenPopup} title="Add new member" />
      </Paper>
      <Popup
        show={showPopup}
        onClose={handleClosePopup}
        title="Enter new member name"
        onSubmit={(name) => onCreateMember(name)}
      />
      <Container size="lg" w="90%">
        <Flex
          bg="white"
          align="center"
          justify="center"
          pt="md"
          pb="md"
          px="lg"
          style={{
            borderTopLeftRadius: "20px",
            borderTopRightRadius: "20px",
          }}
          mt="md"
        >
          <h2
            style={{
              fontWeight: "700",
              fontSize: "1.5rem",
              letterSpacing: "0.5px",
              margin: 0,
              color: "#1a1a1a",
            }}
          >
            {members
              .find((x) => x.group.id === groupId)
              ?.group.name.toUpperCase()}
            <span style={{ color: "#555", fontWeight: "400" }}>
              {" "}
              group members
            </span>
          </h2>
        </Flex>
        {/* Group section */}
        {Array.isArray(members) &&
          members.map((member) => (
            <Flex
              id="group"
              key={member.id}
              align="flex-start"
              p="sm"
              className="shadow"
            >
              <Flex justify="flex-end" align="start">
                <span className="fw-semibold">
                  <IconUser color="blue" /> {member.name}
                </span>

                <Button></Button>
                <Button></Button>

              </Flex>

            </Flex>
          ))}
      </Container>
    </>
  );
}

export default Group;
